def register_shipment_events(event_type: str, events: list[str] | None = None) -> dict[str, list[str]]:
    """Record shipment events of one type and return the events per type."""
    if events is None:
        events = []
    events.append(event_type)
    return {event_type: list(events)}

newest = max(records, key=lambda record: str(record.get("created_at", "")), default=None)
if newest is None:
    return None
return str(newest.get("id"))

base = sum(1 for zone in zones for weight in weights if weight > 0 and zone)
viable: dict[str, int] = {}
for carrier in carriers:
    viable[carrier] = base
return viable

