newest = max(records, key=lambda record: str(record.get("created_at", "")), default=None)
if newest is None:
    return None
return str(newest.get("id"))

count = sum(1 for zone in zones for weight in weights if weight > 0 and zone)
viable = {carrier: count for carrier in carriers}
return viable

